import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
public @interface Check {
    String value();
}

solution.Runner.java:
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class Runner {
    public static List<String> run(Object target) {
        Method[] methods = target.getClass().getDeclaredMethods();
        Arrays.sort(methods, Comparator.comparing(Method::getName));
        List<String> lines = new ArrayList<>();
        for (Method m : methods) {
            Check check = m.getAnnotation(Check.class);
            if (check == null) continue;
            if (m.getParameterCount() > 0) {
                lines.add("SKIP " + check.value() + ": needs arguments");
                continue;
            }
            try {
                m.setAccessible(true);
                m.invoke(target);
                lines.add("pass " + check.value());
            } catch (InvocationTargetException e) {
                lines.add("FAIL " + check.value() + ": " + e.getCause().getMessage());
            } catch (IllegalAccessException e) {
                lines.add("FAIL " + check.value() + ": " + e.getMessage());
            }
        }
        return lines;
    }
}

unitTests:
test("runs the checks in name order", () -> {
    checkEq(Runner.run(new Fixtures.Suite()), java.util.List.of(
        "pass adds",
        "FAIL fails on purpose: expected 3, got 4",
        "pass private ones run too",
        "SKIP cannot run: needs arguments"));
});

test("the annotation is kept at run time", () -> {
    var retention = Check.class.getAnnotation(java.lang.annotation.Retention.class);
    check(retention != null && retention.value() == java.lang.annotation.RetentionPolicy.RUNTIME, "Check needs @Retention(RetentionPolicy.RUNTIME)");
});

