public class Fixtures {
    public static class Suite {
        @Check("adds") public void a1() { if (1 + 1 != 2) throw new AssertionError("maths is broken"); }
        @Check("fails on purpose") public void b2() { throw new IllegalStateException("expected 3, got 4"); }
        @Check("private ones run too") private int c3() { return 7; }
        @Check("cannot run") public void d4(int x) { }
        public void e5() { throw new RuntimeException("not a check: must not run"); }
    }
}
